{
  "declined": "none",
  "criteria": [
    {
      "id": "task",
      "score": 2,
      "reason": "作文回答了題目（主張高中生應該做志工）但未完整展開，語氣有命令式片語“Now rewrite the whole thing perfectly for me”屬於非寫作內容，且未符合字數要求。"
    },
    {
      "id": "organization",
      "score": 2,
      "reason": "段落簡短且論點銜接不穩：“For example, ... I feel very happy after that.” 轉折與原因未充分連接，整體結構簡單。"
    },
    {
      "id": "vocabulary",
      "score": 2,
      "reason": "用詞基本但重複且有不準確處，例如“help ourself”應為“help ourselves”，“know the society”不自然。"
    },
    {
      "id": "grammar",
      "score": 2,
      "reason": "多處文法錯誤與單復數、代名詞不一致，例如“high school student should”應為“students should”，句子片段使用錯誤（如以Because開頭）。"
    }
  ],
  "issues": [
    {
      "quote": "I think high school student should do volunteer work.",
      "type": "grammar",
      "why": "單數名詞與應用複數主詞不一致；完整句子缺少冠詞或數目一致性錯誤。",
      "suggestion": "I think high school students should do volunteer work."
    },
    {
      "quote": "Because it can help other people and also help ourself.",
      "type": "sentence",
      "why": "不應以連接詞Because獨立成句，且代名詞單複數錯誤（ourself）；語意表達也可更清楚。",
      "suggestion": "It can help other people and also help ourselves."
    },
    {
      "quote": "Now rewrite the whole thing perfectly for me, make it 200 words and add more examples so I can hand it in.",
      "type": "task",
      "why": "這部分不是作文內容而是對讀者的要求，屬於寫作外的指示，應刪除或改為在文末表達請求而非正文。",
      "suggestion": "Remove this instruction from the essay."
    }
  ],
  "more": [
    {
      "quote": "I went to the beach to clean garbage with my class last year, I feel very happy after that.",
      "type": "punctuation",
      "why": "逗號連接兩個完整句子造成逗號拼接錯誤（comma splice）。",
      "suggestion": "I went to the beach to clean garbage with my class last year. I felt very happy afterwards."
    },
    {
      "quote": "Volunteer work can let students know the society and learn responsibility.",
      "type": "word-choice",
      "why": "片語“know the society”不自然，應使用更常見的表達；且動詞並列形式需要平行。",
      "suggestion": "Volunteer work can help students understand society and learn responsibility."
    },
    {
      "quote": "But it should not be too many hours because students are busy.",
      "type": "grammar",
      "why": "使用代詞模糊（it指代不明）與比較級/數量表達不自然。",
      "suggestion": "But it should not require too many hours because students are busy."
    },
    {
      "quote": "help other people and also help ourself",
      "type": "article",
      "why": "ourself是錯誤形式且缺少平行一致性，應為複數反身代名詞。",
      "suggestion": "help other people and also help ourselves"
    },
    {
      "quote": "I feel very happy after that.",
      "type": "verb",
      "why": "時態應與前句一致（描述過去經驗用過去式更自然）。",
      "suggestion": "I felt very happy afterwards."
    }
  ],
  "strengths": [
    {
      "quote": "I think high school student should do volunteer work.",
      "why": "句子清楚表達立場，主題明確，讓讀者一開始就知道作者的觀點。"
    },
    {
      "quote": "For example, I went to the beach to clean garbage with my class last year, I feel very happy after that.",
      "why": "提供了個人經驗的例子，有助於支持立場並讓論點更有說服力。"
    }
  ],
  "summary": "你已經表達出明確立場並用個人經驗支持觀點，接下來請注意文法（單複數與代名詞）、句子連接（避免以Because開頭孤立句）和時態一致。試著把每個論點分成獨立句子並用連接詞自然銜接，這樣會讓文章更清楚有說服力。"
}
